"""The office's tariff: the item types it deals in and their rated columns."""

from collections import Counter

MAIN_ITEM_BASE_PREMIUMS = {"sword": 100, "amulet": 60, "staff": 80, "potion": 40}

MAIN_ITEM_INSURANCE_VALUES = {"sword": 1000, "amulet": 600, "staff": 800, "potion": 400}

COMPONENT_TYPES = frozenset({"rune", "moonstone"})
COMPONENT_INSURANCE_VALUE = 250
COMPONENT_BASE_PREMIUM = 25

BASE_PREMIUMS = {
    **MAIN_ITEM_BASE_PREMIUMS,
    **{component: COMPONENT_BASE_PREMIUM for component in COMPONENT_TYPES},
}

INSURANCE_VALUES = {
    **MAIN_ITEM_INSURANCE_VALUES,
    **{component: COMPONENT_INSURANCE_VALUE for component in COMPONENT_TYPES},
}


def tariff_entry_of(tariff, item_type):
    """The office only deals in item types listed in its tariff.

    Premium rating and claim settlement read different columns of the same
    tariff, but recognize the same set of item types.
    """
    if item_type not in tariff:
        raise ValueError(f"unknown item type: {item_type}")
    return tariff[item_type]


def base_premium_of(item_type):
    return tariff_entry_of(BASE_PREMIUMS, item_type)


def insurance_value_of(item_type):
    return tariff_entry_of(INSURANCE_VALUES, item_type)


def is_component(item_type):
    return item_type in COMPONENT_TYPES


def alike_component_counts(item_types):
    """Components are alike when they share the same type."""
    return Counter(item_type for item_type in item_types if is_component(item_type))
=====SETTLEMENT=====
"""How the office settles claims against a policy."""

import math
from fractions import Fraction

from tariff import insurance_value_of

PAYOUT_CAP_MULTIPLE = 2
DEDUCTIBLE_PER_DAMAGE = 100
HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL = 8
HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = Fraction(1, 2)
DRAGON_MATERIAL = "dragon"
DRAGON_MATERIAL_REIMBURSEMENT_RATE = Fraction(1)
STANDARD_REIMBURSEMENT_RATE = Fraction(1)


def item_insurance_value(item):
    """An item is insured at its tariff value, taken from its declared type alone.

    Risk properties such as a curse or a high enchantment rate the premium, not
    the insured value, so they deliberately play no part here.
    """
    return insurance_value_of(item["type"])


def insurance_sum(items):
    """The insurance sum is the sum of the covered items' insurance values."""
    return sum(item_insurance_value(item) for item in items)


def payout_cap(items):
    """The total payout per policy is capped at twice the insurance sum."""
    return PAYOUT_CAP_MULTIPLE * insurance_sum(items)


def is_highly_enchanted_for_reimbursement(item):
    """Damage to items at enchantment level 8 or above is reimbursed at 50 %."""
    return item.get("enchantment", 0) >= HIGH_ENCHANTMENT_REIMBURSEMENT_LEVEL


def is_of_dragon_material(item):
    """Damage to items made of dragon material is fully reimbursed."""
    return item.get("material") == DRAGON_MATERIAL


def reimbursement_rate(item):
    """The office's reimbursement clauses, in the order they take precedence.

    Two clauses can grant a rate to one item. The office states that the high
    enchantment clause wins over dragon material, so it is asked first and the
    clauses never accumulate. An item no clause speaks for is reimbursed in
    full, which is the office's standard treatment and not the dragon clause.
    """
    if is_highly_enchanted_for_reimbursement(item):
        return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
    if is_of_dragon_material(item):
        return DRAGON_MATERIAL_REIMBURSEMENT_RATE
    return STANDARD_REIMBURSEMENT_RATE


def reimbursable_amount(item, amount):
    """The share of a damage amount the office reimburses before the deductible."""
    return reimbursement_rate(item) * amount


def is_admissible_damage_amount(amount):
    """The office entertains a damage only for an amount it could have suffered.

    A negative amount is not a smaller loss but no loss at all, so it states
    nothing the office could settle.
    """
    return amount >= 0


def damage_amount_of(damage):
    """What a damage entry reports as lost, once the office admits the figure.

    A damage the office does not admit is inadmissible and the whole claim is
    rejected, in the same way as a damage no covered item answers for.
    """
    amount = damage["amount"]
    if not is_admissible_damage_amount(amount):
        raise ValueError(f"negative damage amount: {amount}")
    return amount


def damage_payout(item, damage):
    """The office pays the reimbursable share of one damage, less the deductible.

    A deductible of 100 G applies per damage event, so an incident that damages
    two insured items bears it once for each of them.
    """
    return reimbursable_amount(item, damage_amount_of(damage)) - DEDUCTIBLE_PER_DAMAGE


def item_answering_for(unclaimed, item_type):
    """Which still-unclaimed covered item answers for a damage of this type.

    The office settles a damage against any covered item of the damaged type
    that no earlier damage in the same incident has already claimed; it draws
    them in the order the policy lists them. A damage no such item answers for
    is inadmissible and the whole claim is rejected. An unknown type needs no
    separate check: the tariff already refused it when the policy was quoted,
    so no policy can cover one.
    """
    item = next((item for item in unclaimed if item["type"] == item_type), None)
    if item is None:
        raise ValueError(f"item not covered by the policy: {item_type}")
    return item


def damaged_items(items, damages):
    """Each damage entry is settled against a distinct covered item of its type.

    The office works through the incident damage by damage, setting aside each
    item it has settled against so that a later damage cannot claim it twice.
    """
    unclaimed = list(items)
    matched = []
    for damage in damages:
        item = item_answering_for(unclaimed, damage["itemType"])
        unclaimed.remove(item)
        matched.append(item)
    return matched


def rounded_down_in_office_favour(payout):
    """Payouts are rounded down to whole G, in the MHPCO's favour."""
    return math.floor(payout)


def exact_payout(items, damages):
    """A claim is settled damage by damage; the payout is the sum of the parts."""
    return sum(
        (
            damage_payout(item, damage)
            for item, damage in zip(damaged_items(items, damages), damages, strict=True)
        ),
        Fraction(0),
    )


def settle_claim(items, damages):
    """What the claim is assessed at, before any limit the policy imposes."""
    return rounded_down_in_office_favour(exact_payout(items, damages))


def limited_to_remaining_cap(assessed_payout, remaining_cap):
    """The cap limits a claim rather than rejecting it: the office pays what is
    left of the cap and the claim is settled for that, so the remaining cap
    falls by exactly what was paid and never below zero.
    """
    payout = min(assessed_payout, remaining_cap)
    return payout, remaining_cap - payout


def settle_claim_against_cap(items, damages, remaining_cap):
    """A claim is assessed on its own merits, then limited by what the policy has left."""
    return limited_to_remaining_cap(settle_claim(items, damages), remaining_cap)
=====PREMIUM=====
"""How the office rates the premium of a policy."""

import math
from fractions import Fraction

from tariff import (
    COMPONENT_BASE_PREMIUM,
    alike_component_counts,
    base_premium_of,
    is_component,
)

PROCESSING_FEE = 5

COMPONENT_BLOCK_SIZE = 3
COMPONENT_BLOCK_BASE_PREMIUM = 60

CURSE_SURCHARGE_RATE = Fraction(1, 2)
HIGH_ENCHANTMENT_LEVEL = 5
HIGH_ENCHANTMENT_SURCHARGE_RATE = Fraction(3, 10)

LOYALTY_YEARS = 2
LOYALTY_DISCOUNT_RATE = Fraction(1, 5)
FIRST_INSURANCE_SURCHARGE_RATE = Fraction(1, 10)
FOLLOW_UP_CONTRACT_DISCOUNT_RATE = Fraction(3, 20)


def forms_a_building_block(alike_count):
    """A building block requires exactly 3 alike components; 4 do not form one."""
    return alike_count == COMPONENT_BLOCK_SIZE


def component_group_base_premium(count):
    if forms_a_building_block(count):
        return COMPONENT_BLOCK_BASE_PREMIUM
    return count * COMPONENT_BASE_PREMIUM


def policy_base_premium(items):
    item_types = [item["type"] for item in items]
    main_item_total = sum(
        base_premium_of(item_type) for item_type in item_types if not is_component(item_type)
    )
    component_total = sum(
        component_group_base_premium(count)
        for count in alike_component_counts(item_types).values()
    )
    return main_item_total + component_total


def is_cursed(item):
    """A curse is a declared property of the item itself."""
    return bool(item.get("cursed"))


def is_highly_enchanted(item):
    """Enchantment level 5 is already high; level 4 is not."""
    return item.get("enchantment", 0) >= HIGH_ENCHANTMENT_LEVEL


def item_surcharge_rate(item):
    """Item-specific risk policies accumulate: a curse adds 50 %, high enchantment 30 %."""
    rate = Fraction(0)
    if is_cursed(item):
        rate += CURSE_SURCHARGE_RATE
    if is_highly_enchanted(item):
        rate += HIGH_ENCHANTMENT_SURCHARGE_RATE
    return rate


def item_surcharge(item):
    """An item-specific surcharge is charged on that item's own base premium."""
    return item_surcharge_rate(item) * base_premium_of(item["type"])


def item_surcharges(items):
    return sum((item_surcharge(item) for item in items), Fraction(0))


def is_long_standing(customer):
    """A customer is long-standing from exactly 2 years of business onwards."""
    return customer.get("yearsWithMHPCO", 0) >= LOYALTY_YEARS


def is_follow_up_contract(previous_contracts):
    """Every contract after the customer's first is a follow-up contract.

    Contract sequence is scenario state, not a field of the customer record:
    the caller counts the quotes it has already granted this customer.
    """
    return previous_contracts >= 1


def policy_modifier_rate(customer, previous_contracts):
    """Policy-wide modifier policies accumulate.

    Every quote is a first insurance for its items regardless of customer
    history, so that surcharge always applies; loyalty depends on the customer
    record and the follow-up discount on the contract's place in the sequence.
    """
    rate = Fraction(0)
    rate += FIRST_INSURANCE_SURCHARGE_RATE
    if is_long_standing(customer):
        rate -= LOYALTY_DISCOUNT_RATE
    if is_follow_up_contract(previous_contracts):
        rate -= FOLLOW_UP_CONTRACT_DISCOUNT_RATE
    return rate


def policy_modifiers(base, customer, previous_contracts):
    """Policy-wide modifiers are charged on the policy base premium."""
    return policy_modifier_rate(customer, previous_contracts) * base


def rounded_up_in_office_favour(premium):
    """Premiums are rounded up to whole G, in the MHPCO's favour."""
    return math.ceil(premium)


def exact_premium(items, customer, previous_contracts):
    """Item-specific surcharges are charged on their own item, policy-wide
    modifiers on the policy base premium, and the processing fee is added at
    the very end. Kept exact as a Fraction; only the quote is rounded.
    """
    base = policy_base_premium(items)
    return (
        base
        + item_surcharges(items)
        + policy_modifiers(base, customer, previous_contracts)
        + PROCESSING_FEE
    )


def quote_premium(items, customer=None, previous_contracts=0):
    customer = customer or {}
    return rounded_up_in_office_favour(exact_premium(items, customer, previous_contracts))
